CATEGORIES = ['politics', 'crypto', 'sports', 'culture', 'tech', 'climate']


def markets_by_category() -> MarketsByCategory:
    by = {c: [m for m in MARKETS if m.cat == c] for c in CATEGORIES}
    return MarketsByCategory(**by)


